# First sentence of the warranty paragraph; the rest of the line is kept.
TERMS_LEAD = {
    'en': 'We do not promise a particular number of followers, views, clicks, unlocks or revenue. Where a platform lets us read a record of an action we check it, but we do not guarantee that the platform will keep that record available or accurate, and a step we cannot check is recorded as not checked rather than confirmed.',
    'es': 'No prometemos un número concreto de seguidores, visitas, clics, desbloqueos ni ingresos. Cuando una plataforma nos permite leer un registro de una acción lo comprobamos, pero no garantizamos que la plataforma mantenga ese registro disponible o exacto, y el paso que no podemos comprobar se registra como sin comprobar, no como confirmado.',
    'pt-br': 'Não prometemos um número específico de seguidores, visitas, cliques, desbloqueios ou receita. Quando uma plataforma nos permite ler um registro de uma ação, nós o verificamos, mas não garantimos que a plataforma mantenha esse registro disponível ou exato, e a etapa que não podemos verificar é registrada como não verificada, não como confirmada.',
    'ar': 'لا نعد بعدد محدد من المتابعين أو المشاهدات أو النقرات أو عمليات الفتح أو الإيرادات. وحين تتيح لنا منصة قراءة سجل إجراء ما فإننا نتحقق منه، لكننا لا نضمن أن تُبقي المنصة ذلك السجل متاحًا أو دقيقًا، والخطوة التي لا نستطيع فحصها تُسجَّل كغير مفحوصة لا كمؤكّدة.',
}

for loc in LOCALES:
    path = f'messages/{loc}.json'
    data = json.load(io.open(path, encoding='utf-8'))

    faq = data['pages']['faq']['content'].split('### ')
    for index, body in FAQ[loc].items():
        heading = faq[index].split('\n')[0]
        faq[index] = f'{heading}\n{body}\n\n'
    data['pages']['faq']['content'] = '### '.join(faq)

    privacy = data['pages']['privacy']['content'].split('## ')
    heading, body = PRIVACY[loc]
    privacy[8] = f'{heading}\n{body}\n\n'
    data['pages']['privacy']['content'] = '## '.join(privacy)

    lines = data['pages']['terms']['content'].split('\n')
    rest = lines[47].split('. ', 1)[1]
    lines[47] = f'{TERMS_LEAD[loc]} {rest}'
    data['pages']['terms']['content'] = '\n'.join(lines)

    io.open(path, 'w', encoding='utf-8', newline='\n').write(
        json.dumps(data, ensure_ascii=False, indent=2) + '\n'
    )
    print(loc, 'faq/privacy/terms updated')